let S;

function setup() {
	S = ~~(max(windowWidth, windowHeight) / 12);
  createCanvas(S*~~(windowWidth/S), S*~~(windowHeight/S)); // (S = max(windowWidth, windowHeight)), S
	background("black");
	describe("grid of intersecting lines");

  noFill();
  strokeWeight(3);
	colorMode(HSB, 1);
  loop();
}

function draw() {
	blendMode(BLEND);
  // background("rgb(0, 0, 8)");
	background("black")
	blendMode(ADD);

	const maxRot = 0.1;
  for (let y = S; y <= height - S; y += S) {
		for (let x = S; x <= width - S; x += S) {
			const a1 = (noise(x, y, frameCount/123)-0.5) * maxRot;
			const v1 = createVector(S, 0).rotate(a1*TWO_PI);
			const a2 = (noise(y, x, frameCount/321)-0.5) * maxRot;
			const v2 = createVector(0, S).rotate(a2*TWO_PI);
			// console.log(`x:${~~x}, y:${~~y}, a1:${nf(a1, 0, 2)}, a2:${nf(a2, 0, 2)}`)
			// console.log(`1) a:${nf(a1, 0, 2)}, v.x:${~~v1.x}, v.y:${~~v1.y}`)
			// console.log(`2) a:${nf(a2, 0, 2)}, v.x:${~~v2.x}, v.y:${~~v2.y}`)

			// line/clr 1
			stroke(fract(1.0+5*a1), 0.7, 0.7, 1);
			line(x - v1.x, y - v1.y, x + v1.x, y + v1.y)
			// line/clr 2			
			stroke(fract(1.5+5*a2), 0.7, 0.7, 1);
			line(x - v2.x, y - v2.y, x + v2.x, y + v2.y)

		}
  }

  // // noLoop() removed for animation
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
